import{z as A,x as p,o as i,c as B,q as o,j as E,D as e,d as r,s as n,S as l,b as s}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"SR-IOV 与直通","description":"","frontmatter":{"title":"SR-IOV 与直通","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sriov-passthrough.md","filePath":"cs/sriov-passthrough.md","lastUpdated":1791063341000}'),d={name:"cs/sriov-passthrough.md"};function V(F,a,h,u,D,I){const t=p("Mermaid");return i(),B("div",null,[a[2]||(a[2]=o('<h1 id="sr-iov-与直通" tabindex="-1">SR-IOV 与直通 <a class="header-anchor" href="#sr-iov-与直通" aria-label="Permalink to &quot;SR-IOV 与直通&quot;">​</a></h1><div class="epigraph"><p>SR-IOV 让一张物理网卡露出多个 VF：客户直接操作 VF 队列，几乎无 hypervisor 数据面；PF 仍由宿主管。</p><footer>—— 据 PCI-SIG SR-IOV；Linux 对 VF 的说明；[半虚拟](/cs/paravirtualization) 为对照</footer></div><p><a href="/cs/paravirtualization">virtio</a> 仍经宿主。<a href="/cs/dma-coherence">DMA</a> 要 IOMMU。缺口是 <strong>直通</strong>：VF 或整卡交给客户。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PF 出 VF，每个 VF 有自己的 BAR 与队列。客户跑原厂或 VF 驱动。缺口：迁移难（状态在卡上）；与 <a href="/cs/rss-multiqueue">RSS</a> 在 VF 内。本课不把每家网卡工具当文档。</p><p><span class="marginnote">GPU 直通同类但更重。对象是 PCI 功能级虚拟化。</span></p><p><span class="marginnote">术语翻译：VF 就是「一张网卡切出来的分卡」——物理功能 PF 是原卡，每个 VF 带自己的寄存器窗口（BAR）和收发队列，客户机把它当独立小网卡驱动，但收发口仍接到同一块物理芯片。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>宿主启用 SR-IOV → VFIO 绑定 VF → QEMU dist 给客户。对照 virtio：可迁移、可快照更好。对照 <a href="/cs/dpdk-kernel-bypass">DPDK</a>：客户里可再旁路。对照 md RAID：无关。</p>',9)),(i(),E(l,null,{default:e(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PF%5B%22%E7%89%A9%E7%90%86%E5%8A%9F%E8%83%BD%20PF%22%5D%20--%3E%20VF%5B%22%E8%99%9A%E6%8B%9F%E5%8A%9F%E8%83%BD%22%5D%0A%20%20VF%20--%3E%20GUEST%5B%22%E5%AE%A2%E6%88%B7%E7%9B%B4%E6%8E%A5%20DMA%22%5D%0A%20%20IOMMU%5B%22IOMMU%22%5D%20--%3E%20ISO%5B%22%E9%9A%94%E7%A6%BB%20GPA%2FHPA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[r("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,[r("SR-IOV 把数据面还给硬件，换运维灵活性。IOMMU 是安全前提。不要写成网卡广告。与 "),s("a",{href:"/cs/netns-veth"},"netns"),r("：VF 可进宿主 ns 或直通，二选路径。")],-1)),(i(),E(l,null,{default:e(()=>[n(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20VIRTIO%5B%22virtio%20%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20A1%5B%22%E5%AE%A2%E6%88%B7%E5%8F%91%E5%8C%85%22%5D%20--%3E%20A2%5B%22virtio%20%E9%98%9F%E5%88%97%22%5D%20--%3E%20A3%5B%22%E5%AE%BF%E4%B8%BB%20hypervisor%20%E8%BD%AC%E5%8F%91%22%5D%20--%3E%20A4%5B%22%E7%89%A9%E7%90%86%E7%BD%91%E5%8D%A1%22%5D%0A%20%20end%0A%20%20subgraph%20SRIOV%5B%22SR-IOV%20%E7%9B%B4%E9%80%9A%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20B1%5B%22%E5%AE%A2%E6%88%B7%E5%8F%91%E5%8C%85%22%5D%20--%3E%20B2%5B%22VF%20%E9%98%9F%E5%88%97%3Cbr%2F%3E%E5%AE%A2%E6%88%B7%E7%9B%B4%E6%8E%A5%E5%86%99%20DMA%22%5D%20--%3E%20B3%5B%22%E7%89%A9%E7%90%86%E7%BD%91%E5%8D%A1%22%5D%0A%20%20end%0A%20%20A4%20--%3E%20OUT%5B%22%E7%BA%BF%E7%BC%86%22%5D%0A%20%20B3%20--%3E%20OUT%0A%20%20IOMMU%20-.-%3E%7C%22%E5%9C%B0%E5%9D%80%E7%BF%BB%E8%AF%91%E6%8C%A1%E4%BD%8F%E8%B6%8A%E7%95%8C%20DMA%22%7C%20B2%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=o('<p>没有 IOMMU 的直通等于客户可 DMA 宿主。</p><p>实现上：VF 的 MAC/VLAN 由 PF 上的宿主策略管。迁移要热拔 VF 再在对端插，状态难搬。没有 ACS 的桥可能让 DMA 隔离失败。 读法上只引用<a href="/cs/paravirtualization">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / Hypervisor」课序里，对象是 <strong>SR-IOV 与直通</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><p><span class="marginnote">数字实例：virtio 路径每包多一次 hypervisor 软件转发（上下文切换加拷贝或映射），单跳常按微秒计；SR-IOV 客户直接把描述符写给 VF 队列，由网卡 DMA 取包，省掉这一跳——高频交易类负载在乎的就是这 1-2 个微秒。</span></p><p><span class="marginnote">常见误区：初学者容易以为直通的 VF 能像 virtio 网卡一样随手迁移。实际上 VF 的队列状态在卡上，热迁移必须先热拔 VF、迁完在目标机重插——迁移窗口内客户瞬间没有这张网卡，通常是配一条 virtio 备用路径来补。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 ACS 桥问题。不保证无线 SR-IOV。下一课用户态安全直通框架：VFIO。</p><p>版本字段会变，课序钉的是机制对象「SR-IOV 与直通」，不是某一主线内核的结构体名。 后课默认：VF 可直通给客户。VFIO 如何绑 IOMMU 组，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SR-IOV 提供 VF 供客户直通。</li><li>快，但迁移与共享策略变难。</li><li>VFIO 是下一课。</li><li>出处：PCI SR-IOV；Linux networking；VFIO。</li></ul>',11))])}const O=A(d,[["render",V]]);export{m as __pageData,O as default};
